questions.solution:
export function allowed(from, to) {
  const fromFeature = from.split("/")[1];
  const [, toFeature, toFile] = to.split("/");
  if (fromFeature === "shared") return toFeature === "shared";
  if (toFeature === "shared" || toFeature === fromFeature) return true;
  return toFile === "index.js";
}

console.log(
  allowed("src/tasks/service.js", "src/shared/errors.js"),
  allowed("src/shared/errors.js", "src/tasks/index.js"),
  allowed("src/users/service.js", "src/tasks/index.js"),
  allowed("src/users/service.js", "src/tasks/store.js"),
);

